import {measures,volumes,value,valid,quantile,summarize,filterRows,bins,grouped,sortRows,encodeCsv} from './analytics.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
