let hospitals=[],shapes=[],meta={},rows=[],page=0,sortKey='value',sortDirection=-1,mapSummaries=[];
const fmt=(v,d=1)=>v===null||!Number.isFinite(v)?'—':v.toLocaleString('en-US',{maximumFractionDigits:d});
const measure=()=>$('measure').value;
const filters=()=>({state:$('state').value,city:$('city').value,volume:$('volume').value,query:$('query').value});
const labelVolume=v=>v==='Not Available'?'Unknown':v.charAt(0).toUpperCase()+v.slice(1);
