function updateCities(){const state=$('state').value;const cities=[...new Set(hospitals.filter(h=>!state||h.state===state).map(h=>h.city.trim().toUpperCase()))].sort();$('city').innerHTML='<option value="">All cities</option>'+cities.map(c=>`<option value="${esc(c)}">${esc(titleCase(c))}</option>`).join('')}
function selectState(state){$('state').value=state;updateCities();page=0;render()}
function empty(message='No numeric results in this view. Adjust your filters.'){return `<div class="empty">${message}</div>`}
function render(){const m=measure(),cfg=measures[m],f=filters();rows=filterRows(hospitals,f);const s=summarize(rows,m),base=summarize(hospitals,m),locations=new Set(valid(rows,m).map(h=>h.state)).size;
$('context').textContent=`${fmt(rows.length,0)} hospitals in view · ${locations} reporting states / territories · ${f.state?stateNames[f.state]:'All locations'}`;
$('period').textContent=cfg.period;$('measure-description').textContent=`${m.replace('_','-')} · ${cfg.definition}`;
const delta=s.median===null?null:s.median-base.median;
$('kpis').innerHTML=[['Median hospital '+(cfg.unit==='min'?'stay':'rate'),fmt(s.median),cfg.unit,delta===null?'No numeric results':`${delta>0?'+':''}${fmt(delta)} ${cfg.unit==='min'?'min':'percentage points'} vs. all-location median`],['Reporting hospitals',fmt(s.n,0),'',`of ${fmt(s.total,0)} in view · ${locations} reporting locations`],['75th percentile',fmt(s.q3),cfg.unit,'Descriptive threshold · not a clinical target'],['Missing scores',fmt(s.missing,0),'',`${s.total?fmt(100*s.missing/s.total):'—'}% of hospitals in view`]].map(([label,n,u,foot])=>`<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-number">${n}<small>${u}</small></div><div class="kpi-foot">${foot}</div></article>`).join('');
renderMap(m,f);renderRanking(m);renderHistogram(m);renderScatter(m);renderTable();renderInsights(m,s,base);
$('missing-summary').textContent=`For ${m.replace('_','-')}, ${fmt(base.missing,0)} of ${fmt(base.total,0)} hospitals (${fmt(base.missing/base.total*100)}%) have no numeric result in the full snapshot. Missing hospitals are retained in the table and missingness indicator, and excluded from numeric charts.`;
}
function renderMap(m,f){mapSummaries=grouped(filterRows(hospitals,f,true),m,'state');const lookup=new Map(mapSummaries.map(s=>[s.key,s]));const vals=mapSummaries.filter(s=>s.n).map(s=>s.median),min=vals.length?Math.min(...vals):0,max=vals.length?Math.max(...vals):0;const nameToCode=Object.fromEntries(Object.entries(stateNames).map(([k,v])=>[v,k]));
const color=v=>{if(v===null)return '#e3e9ed';const t=max===min?.5:(v-min)/(max-min);return `rgb(${Math.round(213-195*t)},${Math.round(235-183*t)},${Math.round(234-163*t)})`};
$('map').innerHTML=shapes.length?`<svg viewBox="0 0 975 610" aria-label="US state choropleth. Use the state filter or comparison list for equivalent access.">${shapes.map(g=>{const code=nameToCode[g.name],s=lookup.get(code),v=s?.median??null;return `<path class="state-shape ${f.state===code?'selected':''}" d="${g.path}" fill="${color(v)}" data-state="${code}" role="button" tabindex="0" aria-label="${esc(g.name)}, ${v===null?'no numeric results':unit(v,m)+', '+s.n+' reporting hospitals'}. Filter this state."><title>${esc(g.name)}: ${v===null?'No numeric results':unit(v,m)+'; '+s.n+' reporting hospitals'}</title></path>`}).join('')}</svg>`:empty('Map unavailable. Use the state selector or comparison list.');
$('legend').innerHTML=`<span>${fmt(min)} ${measures[m].unit}</span><span class="color-ramp"></span><span>${fmt(max)} ${measures[m].unit}</span><span> · gray: missing</span>`;
$('state-comparison').innerHTML=Object.keys(stateNames).map(code=>lookup.get(code)||{key:code,n:0,total:0,median:null}).sort((a,b)=>(b.median??-1)-(a.median??-1)).map(s=>`<div class="state-comparison-row"><button data-state="${s.key}">${stateNames[s.key]}</button><span>${s.median===null?'No data':unit(s.median,m)}</span><small>${s.n}/${s.total} reporting</small></div>`).join('');
$('map-readout').textContent=f.state?`${stateNames[f.state]} selected. Choose another state or reset to compare all hospitals.`:'Hover or focus a state to inspect its value and reporting count.';
}
function renderRanking(m){const a=sortRows(valid(rows,m),m).slice(0,20),max=a.length?value(a[0],m):1;$('ranking-title').textContent=m==='OP_22'?'20 highest departure rates':'20 longest hospital stays';$('ranking-desc').textContent=`${measures[m].short} · ${measures[m].unit} · ${a.length} hospitals shown`;$('ranking').innerHTML=a.length?a.map((h,i)=>`<button class="hospital-bar" data-hospital="${h.id}" aria-label="${esc(h.name)}, ${h.state}, ${unit(value(h,m),m)}. Open details."><span class="rank">${i+1}</span><span><span class="bar-label">${esc(titleCase(h.name))} <span class="subtle">· ${h.state}</span></span><span class="bar-track"><span class="bar-fill" style="width:${max?value(h,m)/max*100:0}%"></span></span></span><span class="bar-score">${fmt(value(h,m),0)}</span></button>`).join(''):empty();}
function renderHistogram(m){const b=bins(rows,m),n=b.reduce((sum,x)=>sum+x.n,0);$('distribution-desc').textContent=`Distribution of hospital ${m==='OP_22'?'rates':'median stay times'} · ${fmt(n,0)} reporting hospitals`;if(!n){$('histogram').innerHTML=empty();return}const W=610,H=300,l=48,r=18,t=30,bottom=62,w=W-l-r,h=H-t-bottom,max=Math.max(...b.map(x=>x.n)),step=w/b.length;
let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Histogram of ${n} hospital results. Ranges and counts are shown in bar tooltips."><text class="axis-title" x="${l}" y="16">Hospitals</text>`;
for(let i=0;i<=4;i++){const y=t+h-h*i/4;svg+=`<line class="gridline" x1="${l}" x2="${W-r}" y1="${y}" y2="${y}"/><text x="${l-7}" y="${y+4}" text-anchor="end">${Math.round(max*i/4)}</text>`}
svg+=b.map((bin,i)=>{const bh=bin.n/max*h,label=bin.hi===Infinity?`${bin.lo}+`:`${bin.lo}–<${bin.hi}`;return `<g><rect x="${l+i*step+4}" y="${t+h-bh}" width="${step-8}" height="${bh}" rx="2" fill="${i===b.length-1?'#c78952':'#288e93'}"><title>${label} ${measures[m].unit}: ${bin.n} hospitals</title></rect><text x="${l+(i+.5)*step}" y="${t+h-bh-6}" text-anchor="middle">${bin.n}</text><text x="${l+(i+.5)*step}" y="${t+h+22}" text-anchor="middle" style="font-size:10px">${bin.lo}${bin.hi===Infinity?'+':''}</text></g>`}).join('');svg+=`<text class="axis-title" x="${l+w/2}" y="${H-7}" text-anchor="middle">${m==='OP_22'?'Rate (%) · 1-point bins':'ED stay (minutes) · 60-minute bins'}; labels show lower bounds</text></svg>`;$('histogram').innerHTML=svg;
}
function renderScatter(m){const a=valid(rows,m);if(!a.length){$('scatter').innerHTML=empty();$('volume-summary').innerHTML='';return}const W=610,H=315,l=54,r=18,t=32,bottom=48,w=W-l-r,h=H-t-bottom,log=$('log').checked,max=Math.max(...a.map(x=>value(x,m)),1),transform=v=>log?Math.log1p(v):v,y=v=>t+h-transform(v)/transform(max)*h;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Hospital results by ED volume. Group medians and counts appear below. ${log?'Logarithmic log(1 + value) vertical scale.':'Linear vertical scale.'}"><text class="axis-title" x="${l}" y="16">${measures[m].unit}${log?' · log(1 + value) scale':''}</text>`;
for(let i=0;i<=4;i++){const v=log?Math.expm1(Math.log1p(max)*i/4):max*i/4;svg+=`<line class="gridline" x1="${l}" x2="${W-r}" y1="${y(v)}" y2="${y(v)}"/><text x="${l-7}" y="${y(v)+4}" text-anchor="end">${fmt(v,0)}</text>`}
svg+=a.map(hospital=>{const idx=Math.max(0,volumes.indexOf(hospital.volume)),hash=[...hospital.id].reduce((s,c)=>((s*31+c.charCodeAt(0))>>>0),0),x=l+w*(idx+.5)/5+((hash%101)/100-.5)*w/5*.6;return `<circle class="point" cx="${x.toFixed(1)}" cy="${y(value(hospital,m)).toFixed(1)}" r="2.5"><title>${esc(hospital.name)} (${hospital.state}): ${unit(value(hospital,m),m)}; ${labelVolume(hospital.volume)} volume</title></circle>`}).join('');
const stats=volumes.map(v=>({key:v,...summarize(rows.filter(h=>h.volume===v),m)}));svg+=stats.map((s,i)=>{const x=l+w*(i+.5)/5;return `${s.n?`<line x1="${x-22}" x2="${x+22}" y1="${y(s.median)}" y2="${y(s.median)}" stroke="#c57438" stroke-width="4"><title>Median: ${unit(s.median,m)}; n=${s.n}</title></line>`:''}<text x="${x}" y="${H-18}" text-anchor="middle">${labelVolume(s.key)}</text>`}).join('')+'</svg>';$('scatter').innerHTML=svg;$('volume-summary').innerHTML=stats.map(s=>`<span>${labelVolume(s.key)}: ${s.n?unit(s.median,m):'—'} · n=${fmt(s.n,0)}</span>`).join('');}
function tableRows(){return sortRows($('missing').checked?rows.filter(h=>value(h,measure())===null):rows,measure(),sortKey,sortDirection)}
function renderTable(){const m=measure(),a=tableRows(),pages=Math.max(1,Math.ceil(a.length/15));page=Math.max(0,Math.min(page,pages-1));$('hospital-rows').innerHTML=a.slice(page*15,(page+1)*15).map(h=>`<tr><td><button data-hospital="${h.id}">${esc(titleCase(h.name))}</button><small>CMS ${h.id}</small></td><td>${h.state}</td><td>${esc(titleCase(h.city))}</td><td><span class="volume-tag">${labelVolume(h.volume)}</span></td><td class="${value(h,m)===null?'na':''}">${value(h,m)===null?'Not available':unit(value(h,m),m)}</td><td>${esc(h.metrics[m]?.footnote||'—')}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No hospitals match these table filters.</div></td></tr>';$('table-count').textContent=`${a.length?`${page*15+1}–${Math.min((page+1)*15,a.length)}`:'0'} of ${fmt(a.length,0)} hospitals${$('missing').checked?' · missing results only':''}`;$('page-label').textContent=`${page+1} / ${pages}`;$('prev').disabled=page===0;$('next').disabled=page>=pages-1;$('download').disabled=!a.length;$('score-heading').textContent=(m==='OP_22'?'Rate (%)':'ED stay (min)')+(sortKey==='value'?(sortDirection===1?' ↑':' ↓'):' ↕');document.querySelectorAll('[data-sort]').forEach(b=>b.parentElement.setAttribute('aria-sort',b.dataset.sort===sortKey?(sortDirection===1?'ascending':'descending'):'none'));}
function renderInsights(m,s,base){if(!s.total){$('findings').innerHTML=empty('No hospitals match. Reset the filters to see findings.');$('recommendations').innerHTML=empty('Recommendations will appear when hospitals are in view.');return}const high=summarize(rows.filter(h=>h.volume==='very high'),m),low=summarize(rows.filter(h=>h.volume==='low'),m),top=s.n?sortRows(valid(rows,m),m)[0]:null;const above=valid(rows,m).filter(h=>value(h,m)>base.q3),highAbove=above.filter(h=>['high','very high'].includes(h.volume));
const paired=rows.filter(h=>value(h,'OP_18c')!==null&&value(h,'OP_18b')!==null),diff=quantile(paired.map(h=>value(h,'OP_18c')-value(h,'OP_18b')),.5);const signal=paired.filter(h=>value(h,'OP_18c')>value(h,'OP_18b')).length;
const items=[['THE SPREAD',s.n?`${unit(s.q1,m)} to ${unit(s.q3,m)}`:'No numeric results',s.n?`The middle 50% of hospital results falls in this range. ${esc(titleCase(top.name))} (${top.state}) has the highest result in this view: ${unit(value(top,m),m)}.`:'This selection has hospitals, but no reported numeric results for the chosen measure.'],['VOLUME COMPARISON',high.n&&low.n?`${unit(high.median,m)} vs. ${unit(low.median,m)}`:'Compare volume groups',high.n&&low.n?`Very-high-volume hospitals (n=${fmt(high.n,0)}) versus low-volume hospitals (n=${fmt(low.n,0)}), using group medians. This is an association; patient mix and reporting periods may differ.`:'Both low and very-high volume groups need reported results for this comparison. Broaden the volume or location filters.'],['REPORTING GAP',`${fmt(s.missing,0)} hospitals without a score`,`${fmt(100*s.missing/s.total)}% of hospitals in this view have no numeric ${m.replace('_','-')} result. They remain in the table and are excluded from the charts.`]];
$('findings').innerHTML=items.map(([tag,title,text])=>`<article class="finding"><div class="eyebrow">${tag}</div><h3>${title}</h3><p>${text}</p></article>`).join('');
const recs=[['Prioritize a patient-flow review',`Start with high- or very-high-volume hospitals above the all-location 75th percentile (${unit(base.q3,m)}). Review arrival patterns, triage, diagnostics, discharge steps, and staffing by shift before choosing a capacity intervention.`,`${fmt(highAbove.length,0)} hospitals in this view meet that descriptive screen; ${fmt(above.length,0)} hospitals across all volume groups exceed the benchmark.`],['Review mental health pathways',paired.length?`Compare mental health assessment and referral processes at the ${fmt(signal,0)} matched hospitals where the mental health stay exceeds the general-patient stay. Ask about transfer coordination and local behavioral health service availability before considering resource changes.`:'Seek complete mental health and general-patient reporting before making a matched comparison. Do not infer that absent reports mean no behavioral health need.',paired.length?`${fmt(paired.length,0)} hospitals report both OP-18c and OP-18b. Median within-hospital difference: ${diff>0?'+':''}${fmt(diff)} minutes. Patient populations differ; this is not a causal estimate.`:'No matched OP-18c / OP-18b hospitals in the current view.'],['Close reporting gaps first',s.missing?`Contact the ${fmt(s.missing,0)} hospitals without a numeric score. Use CMS footnotes to separate reporting issues, insufficient samples, and inapplicability; obtain local throughput data before ranking these facilities.`:'Preserve reporting completeness and review the footnotes and sample fields of reported results before making a funding decision.',`${fmt(s.n,0)} of ${fmt(s.total,0)} hospitals report a numeric value for the selected measure. Missingness is ${fmt(100*s.missing/s.total)}%.`]];
$('recommendations').innerHTML=recs.map(([title,text,evidence],i)=>`<article class="recommendation"><span class="step">0${i+1}</span><h3>${title}</h3><p>${text}</p><p class="evidence">Evidence · ${evidence}</p></article>`).join('');}
function openHospital(id){const h=hospitals.find(x=>x.id===id);if(!h)return;const m=measure(),benchmark=summarize(hospitals,m).median;$('hospital-detail').innerHTML=`<h2>${esc(titleCase(h.name))}</h2><p>${esc(titleCase(h.city))}, ${stateNames[h.state]} ${esc(h.zip)} · CMS ID ${h.id}<br>${esc(titleCase(h.county))} County / Parish · ED volume: ${labelVolume(h.volume)} (2024)</p><p><strong>${measures[m].short}: ${value(h,m)===null?'Not available':unit(value(h,m),m)}</strong> · All-location hospital median: ${unit(benchmark,m)}</p><div class="table-wrap"><table><thead><tr><th>Measure</th><th>Result</th><th>Sample field</th><th>Footnote</th></tr></thead><tbody>${Object.entries(measures).map(([k,cfg])=>`<tr><td>${k.replace('_','-')}<br>${cfg.short}<div class="source-period">${cfg.period}</div></td><td>${value(h,k)===null?'Not available':unit(value(h,k),k)}</td><td>${esc(h.metrics[k]?.sample||'Not supplied')}</td><td>${esc(h.metrics[k]?.footnote||'—')}</td></tr>`).join('')}</tbody></table></div><p><strong>Selected-measure footnote:</strong> ${esc(note(h.metrics[m]?.footnote))}.</p><p>The sample field is reproduced from CMS. It is not an annual visit count, and sample sizes from different populations must not be added together. Numeric scores may carry reporting qualifications.</p><p><a href="https://www.medicare.gov/care-compare/details/hospital/${encodeURIComponent(h.id)}" target="_blank" rel="noopener">Hospital on Medicare Care Compare ↗</a> · <a href="https://data.cms.gov/provider-data/dataset/y9us-9xdf" target="_blank" rel="noopener">Read CMS footnotes ↗</a></p>`;$('hospital-dialog').showModal();}
function exportCsv(){const m=measure(),data=tableRows(),csvRows=[['Facility ID','Facility Name','State','City','ED volume (2024)','Measure ID','Score','Unit','Sample','Footnote','Start Date','End Date','Source'],...data.map(h=>[h.id,h.name,h.state,h.city,h.volume,m,value(h,m)??'Not Available',measures[m].unit,h.metrics[m]?.sample,h.metrics[m]?.footnote,...meta.periods[m],'https://data.cms.gov/provider-data/dataset/yv7e-xc69'])];const csv=encodeCsv(csvRows);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`ed-access-${$('state').value||'all'}-${m}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function registerTool(){if(!document.modelContext?.registerTool)return;Promise.resolve(document.modelContext.registerTool({name:'configure_ed_dashboard',description:'Set the dashboard state and measure; reset city, volume, and hospital search. Return reporting counts and median.',inputSchema:{type:'object',properties:{state:{type:'string',description:'State/territory code or empty string for all'},measure:{type:'string',enum:Object.keys(measures)}},required:['state','measure'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Object.hasOwn(measures,input.measure)||(input.state!==''&&!Object.hasOwn(stateNames,input.state)))throw Error('Invalid state or measure');$('measure').value=input.measure;$('query').value='';$('volume').value='';$('missing').checked=false;selectState(input.state);return summarize(rows,input.measure)}})).catch(()=>{});}
$('filters').addEventListener('submit',e=>e.preventDefault());$('state').addEventListener('change',()=>{updateCities();page=0;render()});['city','volume','measure'].forEach(id=>$(id).addEventListener('change',()=>{page=0;render()}));let searchTimer;$('query').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=0;render()},180)});$('reset').onclick=()=>{if(!hospitals.length)return;$('measure').value='OP_18b';$('volume').value='';$('query').value='';$('missing').checked=false;$('log').checked=false;sortKey='value';sortDirection=-1;selectState('')};$('log').onchange=()=>renderScatter(measure());$('missing').onchange=()=>{page=0;renderTable()};$('prev').onclick=()=>{page--;renderTable()};$('next').onclick=()=>{page++;renderTable()};$('download').onclick=exportCsv;$('close-dialog').onclick=()=>$('hospital-dialog').close();
document.addEventListener('click',e=>{const s=e.target.closest('[data-state]'),h=e.target.closest('[data-hospital]'),sort=e.target.closest('[data-sort]');if(s)selectState(s.dataset.state);if(h)openHospital(h.dataset.hospital);if(sort){sortDirection=sortKey===sort.dataset.sort?-sortDirection:(sort.dataset.sort==='value'?-1:1);sortKey=sort.dataset.sort;page=0;renderTable()}});
document.addEventListener('keydown',e=>{const s=e.target.closest('path[data-state]');if(s&&['Enter',' '].includes(e.key)){e.preventDefault();selectState(s.dataset.state)}});
function mapFocus(e){const el=e.target.closest('path[data-state]');if(!el)return;const code=el.dataset.state,s=mapSummaries.find(x=>x.key===code);$('map-readout').textContent=`${stateNames[code]} · ${s?.n?unit(s.median):'No numeric data'} · ${s?.n||0} of ${s?.total||0} hospitals reporting.`}
$('map').addEventListener('pointerover',mapFocus);$('map').addEventListener('focusin',mapFocus);
async function init(){try{const response=await fetch('hospitals.json');if(!response.ok)throw Error('Hospital data unavailable');const payload=await response.json();hospitals=payload.hospitals;meta=payload.meta;try{const r=await fetch('states.json');if(r.ok)shapes=await r.json()}catch{}$('measure').innerHTML=Object.entries(measures).map(([k,c])=>`<option value="${k}">${c.title}</option>`).join('');$('state').innerHTML='<option value="">All states & territories</option>'+Object.entries(stateNames).sort((a,b)=>a[1].localeCompare(b[1])).map(([k,n])=>`<option value="${k}">${n}</option>`).join('');$('volume').innerHTML='<option value="">All volumes</option>'+volumes.map(v=>`<option value="${v}">${labelVolume(v)}</option>`).join('');updateCities();['measure','state','city','volume','query'].forEach(id=>$(id).disabled=false);$('provenance').innerHTML=`${fmt(meta.sourceRows,0)} source rows → ${fmt(meta.selectedRows,0)} emergency-care records → ${fmt(meta.hospitalCount,0)} unique hospitals.<br>No duplicate Facility ID + Measure ID pairs.<br>Original CSV SHA-256: <code>${meta.sha256}</code>`;render();registerTool()}catch(e){$('context').innerHTML='<span class="error">The hospital snapshot could not load. Reload this page or use the source CSV link below.</span>';console.error(e)}}
init();
